/**
 * Column & schema helpers shared by every module's `tables.ts`.
 *
 * Conventions (see docs/data-model.md):
 * - Every module schema uses `snakeCase.schema(...)` so camelCase TypeScript
 *   property keys automatically map to `snake_case` PostgreSQL columns without
 *   repeating column name strings in column builders.
 * - Primary keys are UUIDv7 generated by Postgres 18 (`uuidv7()`): time-ordered,
 *   so `ORDER BY id` is insertion order and B-tree inserts stay append-only.
 *   The application may still pass an id explicitly (e.g. Cluster entity ids).
 * - Money is `bigint` cents (never float, never numeric-as-string).
 * - Instants are `timestamptz`; calendar days are `date` (string mode).
 * - A "competência" is the first day of the month as a `date`.
 *
 * Kernel rule: this file must never import from `src/modules/*`.
 */
import {type SQL, sql} from "drizzle-orm"
import {type AnyPgColumn, bigint, date, timestamp, uuid} from "drizzle-orm/pg-core"

export const id = () => uuid().primaryKey().default(sql`uuidv7()`)

/** Tenant scope. Every business table has it (rule 8). */
export const companyId = () => uuid().notNull()

export const timestamptz = () => timestamp({withTimezone: true, mode: "date"})

export const createdAt = () => timestamptz().notNull().defaultNow()

export const updatedAt = () =>
  timestamptz()
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date())

/** Calendar day (no time, no zone), e.g. `"2026-11-21"`. */
export const day = () => date({mode: "string"})

/** Integer amount in BRL cents. Safe up to 2^53 (≈ R$ 90 trillion). */
export const cents = () => bigint({mode: "number"})

/** Reference month, stored as its first day: `"2026-11-01"`. */
export const competence = () => day()

/** CHECK expression: a `competence` column must be the first day of a month. */
export const isFirstOfMonth = (column: AnyPgColumn): SQL => sql`extract(day from ${column}) = 1`
